Definition w4s32_EcA_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x5 x6 x7 x8 x9 x10 x12 x13 x16 x17 x19 x20 x22 x23 x24 x26 x27 x28 x29 x30 x31 : word)
         (P SS n SBL SBH S2 L2 PTR PN U BITS PP PE DESC : Z),
    PTR = PN + U ->
    w4s_src_ctx RNG mm SS n SBL SBH ->
    n < 2^26 ->
    SS <= S2 ->
    S2 + L2 <= SS + n ->
    rw_cells asegs mm (P + 104) [C8 (Z_to_bv 64 DESC)] ->
    rw_cells asegs mm (P + 200) [C8 (Z_to_bv 64 PE)] ->
    rng RNG P 496 ->
    0x10007fff8000 <= P ->
    P + 496 <= 2^47 ->
    KXGoM.apart SS n P 496 ->
    S2 < PTR < S2 + 8 ->
    PTR - S2 + 8 <= L2 ->
    0 <= BITS <= 64 ->
    0 <= U <= 8 ->
    S2 <= PN ->
    0 <= DESC < 2^64 ->
    0 <= PE < 2^64 ->
    (forall (cw : word) (y5 y6 y11 y13 y14 y17 : word),
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp y5 y6 x7 x8 x9 x10 y11 (Z_to_bv 64 PN) y13 y14 (Z_to_bv 64 PP) x16
           y17 (Z_to_bv 64 S2) x19 x20 (Z_to_bv 64 DESC) x22 x23 x24 (Z_to_bv 64 PTR) x26 x27 (Z_to_bv 64 (-8 * U +
           BITS)) (Z_to_bv 64 PE) x30 cw) F (Z_to_bv 64 0x9232c) fc None mm (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 x8 x9 x10 (Z_to_bv 64 U) x12 x13 (Z_to_bv 64 2147450880)
        (Z_to_bv 64 PP) x16 x17 (Z_to_bv 64 S2) x19 x20 (Z_to_bv 64 BITS) x22 x23 x24 (Z_to_bv 64 PTR) x26 x27 x28 x29
        x30 x31) F (Z_to_bv 64 0x921b4) fc None mm (seg_rom asegs)).

