(* [comment removed for export] *)
Definition w4s32_T_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x5 x6 x7 x8 x9 x10 x12 x13 x14 x16 x18 x19 x20 x21 x23 x24 x25 x26 x27 x29 x30 : word)
         (P DT4 DBL DBH DST dcap tl PP B C : Z) (cells : list deltX1) (obuf : list Z),
    w4s1_dctx RNG mm P DT4 DBL DBH DST dcap tl ->
    mem_inv asegs mm ->
    x1_table_ok cells tl ->
    bytes_at asegs mm DT4 (firstn (Z.to_nat (2 * 2^tl)) (x1_bytes cells)) ->
    u8arr asegs mm DST (map (Z_to_bv 8) obuf) ->
    zlen obuf = dcap ->
    rw_cells asegs mm (P + 136) [C8 (Z_to_bv 64 2147450880)] ->
    DST <= PP ->
    PP + 1 <= DST + dcap ->
    0 <= B <= 2^40 ->
    0 <= C < 2^64 ->
    (forall (mm' : amem) (N : Z) (y5 y6 y14 y30 : word),
       munch [(DST, DST + dcap)] mm mm' ->
       wmono asegs mm mm' ->
       mem_inv asegs mm' ->
       (exists obuf', u8arr asegs mm' DST (map (Z_to_bv 8) obuf') /\ zlen obuf' = dcap) ->
       0 <= N <= 12 ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp y5 y6 x7 x8 x9 x10 (Z_to_bv 64 (PP + 1)) x12 (Z_to_bv 64 (PP + 1))
           y14 (Z_to_bv 64 (PP + 1)) x16 (Z_to_bv 64 (64 - tl)) x18 x19 x20 x21 (Z_to_bv 64 DT4) x23 x24 x25 x26 x27
           (Z_to_bv 64 (B + N)) x29 y30 (Z_to_bv 64 C)) F (Z_to_bv 64 0x923a4) fc None mm' (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 x8 x9 x10 (Z_to_bv 64 PP) x12 x13 x14 (Z_to_bv 64 PP) x16
        (Z_to_bv 64 (64 - tl)) x18 x19 x20 x21 (Z_to_bv 64 DT4) x23 x24 x25 x26 x27 (Z_to_bv 64 B) x29 x30 (Z_to_bv 64
        C)) F (Z_to_bv 64 0x9233c) fc None mm (seg_rom asegs)).

